/* Night Elite Ludo frontend. Demo adapter (localStorage) sits behind `API`; swap its methods for fetch('/api/...') calls. */
const CFG={DEMO_WALLET:true,ENABLE_REAL_MONEY:false,ENABLE_CASHFREE:false,ENABLE_KYC:false,FEE:.025,NOTICE:'Demo mode: sandbox coins only. No real money is used.',WA:'https://wa.me/918302402126',OTP_COOLDOWN:30,OTP_MAX:5,MIN_STAKE:50};
const $=(s,r=document)=>r.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>'₹'+Number(n).toFixed(2),KEY='fb_demo_v1';
const BOTS=['Kartik tiwari','Gujjar ji','TurboWin','PowerDice','LuckyChamp','Kingkhan','NightHawk'];
let S=JSON.parse(localStorage.getItem(KEY)||'null')||{user:null,battles:[],ledger:[],notes:[],otp:null};
const FBC=window.FB_CONFIG||{},REAL=!!(FBC.SUPABASE_URL&&FBC.SUPABASE_ANON_KEY&&window.supabase);let UID=null;if(REAL)S={user:null,battles:[],ledger:[],notes:[],otp:null};
const save=()=>{REAL||localStorage.setItem(KEY,JSON.stringify(S))};
const toast=m=>{const t=$('#toast');t.textContent=m;t.className='on';clearTimeout(toast.t);toast.t=setTimeout(()=>t.className='',2200)};
const prize=s=>+(s*2*(1-CFG.FEE*2)).toFixed(2);
const seed=()=>{if(S.battles.filter(b=>b.st==='open'&&b.bot).length<4){for(let i=0;i<5;i++){const s=[100,200,450,1100,2000][i];S.battles.push({id:crypto.randomUUID(),st:'open',by:BOTS[i],bot:1,stake:s,at:Date.now()-i*1e5})}if(!S.battles.some(b=>b.st==='running'&&b.bot))[['Kingkhan','Ps meeNa',200],['EliteRoll','NightHawk',1000],['PowerDice','LuckyChamp',2850]].forEach(([a,c,x])=>S.battles.push({id:crypto.randomUUID(),st:'running',by:a,opp:c,bot:1,stake:x,at:Date.now()}));save()}};
const led=(t,a,note)=>{S.ledger.unshift({id:crypto.randomUUID(),t,a,note,at:Date.now()});S.ledger=S.ledger.slice(0,200)};
/* ---- API adapter (demo) ---- */
const API={
 async sendOtp(p){if(!/^[6-9]\d{9}$/.test(p))throw Error('Enter a valid 10-digit mobile number.');
  if(S.otp&&Date.now()-S.otp.at<CFG.OTP_COOLDOWN*1e3)throw Error('Wait before requesting another OTP.');
  S.otp={p,at:Date.now(),tries:0};save()},
 async verifyOtp(c){const o=S.otp;if(!o)throw Error('Request an OTP first.');if(Date.now()-o.at>3e5)throw Error('OTP expired. Request a new one.');
  if(++o.tries>CFG.OTP_MAX){S.otp=null;save();throw Error('Too many attempts. Request a new OTP.')}
  if(!/^\d{6}$/.test(c))throw Error('Enter the 6-digit OTP.');save();
  if(!S.user)S.user={phone:o.p,name:'FastUser'+Math.floor(1000+Math.random()*9000),funds:0,income:0,won:0,games:0,kyc:false,ref:Math.random().toString(36).slice(2,8).toUpperCase(),refs:0};
  S.otp=null;seed();save()},
 async addCash(a){if(!CFG.DEMO_WALLET)throw Error('Payments are not enabled.');if(!(a>=10&&a<=10000))throw Error('Enter ₹10 to ₹10,000.');S.user.funds+=a;led('Demo deposit',a,'Sandbox money');save()},
 async create(s){if(!(s>=CFG.MIN_STAKE))throw Error('Minimum entry is '+CFG.MIN_STAKE+' coins.');if(s>S.user.funds)throw Error('Not enough deposit coins. Add cash first.');
  S.user.funds-=s;led('Battle stake locked',-s,'Created battle');S.battles.unshift({id:crypto.randomUUID(),st:'open',by:S.user.name,mine:1,stake:s,at:Date.now()});save()},
 async cancel(id){const b=S.battles.find(x=>x.id===id&&x.mine&&x.st==='open');if(!b)return;b.st='cancelled';S.user.funds+=b.stake;led('Stake refunded',b.stake,'Battle cancelled');save()},
 async join(id){const b=S.battles.find(x=>x.id===id&&x.st==='open'&&!x.mine);if(!b)throw Error('Battle is no longer open.');if(b.stake>S.user.funds)throw Error('Not enough deposit coins. Add cash first.');
  S.user.funds-=b.stake;led('Battle stake locked',-b.stake,'Joined '+b.by);b.st='running';b.opp=S.user.name;b.joined=1;b.end=Date.now()+8e3;save()},
 settle(){let ch=0;S.battles.forEach(b=>{if(b.mine&&b.st==='open'&&Date.now()-b.at>6e3){b.st='running';b.opp=BOTS[Math.floor(Math.random()*BOTS.length)];ch=1}});(S.wds||[]).forEach(w=>{if(w.status==='pending'&&Date.now()>w.at+1e4){w.status='paid';S.notes.unshift({m:'Withdrawal of ₹'+w.amount+' paid',at:Date.now(),r:0});ch=1}});S.battles.forEach(b=>{if(b.st==='running'&&b.end<=Date.now()&&b.joined&&b.auto){b.st='done';const w=Math.random()<.5;b.won=w;S.user.games++;
   if(w){const p=prize(b.stake);S.user.income+=p;S.user.won+=p;led('Battle won',p,'vs '+b.by);S.notes.unshift({m:'You won '+fmt(p)+' against '+b.by,at:Date.now(),r:0})}
   else S.notes.unshift({m:'You lost '+b.stake+' coins against '+b.by,at:Date.now(),r:0});ch=1}});if(ch)save();return ch},
 async ticket(sj,b){if(sj.length<3||b.length<5)throw Error('Add a subject and a message.');S.tickets=S.tickets||[];if(S.tickets.filter(t=>t.status==='open').length>=5)throw Error('Too many open tickets.');S.tickets.unshift({id:crypto.randomUUID(),subject:sj,status:'open',reply:null,created_at:new Date().toISOString()});save()},
 demoFinish(id,won){const b=S.battles.find(x=>x.id===id);if(!b||b.st!=='running')return;b.st='done';b.won=won;S.user.games++;const vs=b.mine?b.opp:b.by;if(won){const p=prize(b.stake);S.user.income+=p;S.user.won+=p;led('Battle won',p,'vs '+vs);S.notes.unshift({m:'You won '+(+p.toFixed(2))+' coins against '+vs,at:Date.now(),r:0})}else S.notes.unshift({m:'You lost '+b.stake+' coins against '+vs,at:Date.now(),r:0});if(S.games)delete S.games[id];save()},
 async kyc(n,e,m,b,a,ad){if(S.user.kyc||S.user.kycs==='pending')throw Error('KYC already submitted.');if(n.trim().length<3)throw Error('Enter your full name.');if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(e))throw Error('Enter a valid email address.');if(!/^[6-9]\d{9}$/.test(m))throw Error('Enter a valid 10-digit mobile number.');if(!aadhaarOk(a))throw Error('Invalid Aadhaar number.');if((ad||'').trim().length<10)throw Error('Enter your full address.');if(!KB.f||!KB.b)throw Error('Add the front and back photos of your Aadhaar.');if(!b||new Date(b)>new Date(Date.now()-18*31557600000))throw Error('You must be 18 or older.');S.kycForm={name:n.trim(),email:e,mobile:m,dob:b,last4:a.slice(-4),address:ad.trim()};S.user.kycs='pending';save()},
 async withdraw(a,m,d){if(!S.user.kyc)throw Error('Complete KYC to withdraw.');if(!(a>=100))throw Error('Minimum withdrawal is ₹100.');if(a>S.user.income)throw Error('Not enough winning coins.');if(m==='upi'?!/^[\w.\-]{2,}@[A-Za-z]{2,}$/.test(d):d.trim().length<5)throw Error('Enter valid payout details.');S.user.income-=a;led('Withdrawal requested',-a,'Demo withdrawal');S.wds=S.wds||[];S.wds.unshift({id:crypto.randomUUID(),amount:a,status:'pending',method:m,at:Date.now()});save()}
};
/* ---- Real backend adapter (Supabase + /api). Active only when js/config.js has URL + anon key. ---- */
const EM={TOO_MANY:'Too many attempts. Wait a few minutes and try again.',QR_UNAVAILABLE:'Could not generate the QR right now. Try again.',PAYMENTS_DISABLED:'Payments are not available right now.',NOT_FOUND:'Payment not found.',BAD_ADDRESS:'Enter your full address.',DOCS_MISSING:'Add the front and back photos of your Aadhaar.',BAD_AADHAAR:'Invalid Aadhaar number.',AADHAAR_USED:'This Aadhaar is already linked to another account.',BAD_EMAIL:'Enter a valid email address.',BAD_MOBILE:'Enter a valid 10-digit mobile number.',KYC_UNAVAILABLE:'KYC is temporarily unavailable.',KYC_EXISTS:'KYC already submitted.',BAD_KYC:'Enter your full name and the last 4 characters of your ID.',UNDERAGE:'You must be 18 or older.',MIN_WITHDRAW:'Amount is below the minimum withdrawal.',BAD_DETAIL:'Enter valid payout details.',PAYMENTS_DISABLED:'Online payments are not enabled.',PAYMENT_FAILED:'Could not start the payment. Try again.',BAD_TICKET:'Add a subject (3+ characters) and a message (5+).',TOO_MANY_TICKETS:'You have 5 open tickets. Wait for a reply first.',BAD_CODE:'Room code: 4–12 letters or numbers.',ALREADY_REPORTED:'You already reported this result.',BAD_CLAIM:'Invalid result.',INSUFFICIENT_FUNDS:'Not enough coins. Add cash first.',BAD_STAKE:'Enter a whole number, minimum 50 coins.',NOT_OPEN:'Battle is no longer open.',OWN_BATTLE:'You cannot join your own battle.',NOT_ALLOWED:'Not allowed.',DEMO_DISABLED:'Adding cash is disabled.',BAD_AMOUNT:'Enter ₹10 to ₹10,000.',WITHDRAW_DISABLED:'Withdrawals are disabled in demo mode.',KYC_REQUIRED:'Complete KYC to withdraw.',AUTH:'Please log in again.',BAD_PHONE:'Enter a valid 10-digit mobile number.',COOLDOWN:'Wait 30 seconds before requesting another OTP.',RATE_LIMIT:'Too many OTP requests. Try again later.',OTP_UNAVAILABLE:'OTP service is unavailable. Try later.',SMS_BALANCE:'SMS service is out of balance. Contact support.',SMS_FAILED:'Could not send OTP. Try again.',OTP_EXPIRED:'OTP expired. Request a new one.',WRONG_OTP:'Wrong OTP.',TOO_MANY_ATTEMPTS:'Too many attempts. Request a new OTP.'};
const em=m=>{const k=Object.keys(EM).find(k=>String(m).includes(k));return k?EM[k]:'Something went wrong. Try again.'};
let sb=null;
if(REAL){sb=window.supabase.createClient(FBC.SUPABASE_URL,FBC.SUPABASE_ANON_KEY);
 const http=async(p,b)=>{let r,j;try{r=await fetch('/api'+p,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)});j=await r.json()}catch{throw Error('Network error. Check your connection.')}if(!r.ok)throw Error(em(j.error));return j};
 const rpc=async(n,a)=>{const{error}=await sb.rpc(n,a);if(error)throw Error(em(error.message));await API.refresh()};
 Object.assign(API,{
  async sendOtp(p){if(!/^[6-9]\d{9}$/.test(p))throw Error(EM.BAD_PHONE);await http('/auth/send-otp',{phone:p});S.otp={p,at:Date.now(),tries:0}},
  async verifyOtp(c){if(!S.otp)throw Error('Request an OTP first.');if(!/^\d{6}$/.test(c))throw Error('Enter the 6-digit OTP.');
   const j=await http('/auth/verify-otp',{phone:S.otp.p,code:c});await sb.auth.setSession({access_token:j.session.access_token,refresh_token:j.session.refresh_token});S.otp=null;
   const ref=new URLSearchParams(location.search).get('ref');if(ref)await sb.rpc('apply_referral',{p_code:ref});await API.refresh()},
  create:s=>rpc('create_battle',{p_stake:s}),join:id=>rpc('join_battle',{p_id:id}),cancel:id=>rpc('cancel_battle',{p_id:id}),
  addCash:a=>rpc('demo_add_cash',{p_amount:a}),withdraw:(a,m,d)=>rpc('request_withdrawal',{p_amount:a,p_method:m,p_detail:d}),async kyc(n,e,m,b,a,ad){if(!KB.f||!KB.b)throw Error('Add the front and back photos of your Aadhaar.');for(const[k,nm]of[['f','front'],['b','back']]){const{error}=await sb.storage.from('kyc').upload(`${UID}/${nm}.jpg`,KB[k],{upsert:true,contentType:'image/jpeg'});if(error)throw Error('Could not upload your photos. Try again.')}const{data:{session}}=await sb.auth.getSession();const x=await fetch('/api/kyc/submit',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+session.access_token},body:JSON.stringify({name:n,email:e,mobile:m,dob:b,aadhaar:a,address:ad})}).then(r=>r.json()).catch(()=>({error:'NETWORK'}));if(x.error)throw Error(em(x.error));await API.refresh()},
  async apiF(path,o={}){const{data:{session}}=await sb.auth.getSession();return fetch(path,{...o,headers:{'Content-Type':'application/json',Authorization:'Bearer '+(session?session.access_token:'')}}).then(r=>r.json()).catch(()=>({error:'NETWORK'}))},
  async createQr(a){const x=await API.apiF('/api/payments/create-order',{method:'POST',body:JSON.stringify({amount:a})});if(!x.order_id)throw Error(em(x.error));return x},
  settle:()=>0,ticket:(s,b)=>rpc('create_ticket',{p_subject:s,p_body:b}),setRoom:(id,c)=>rpc('set_room_code',{p_id:id,p_code:c}),report:(id,c)=>rpc('report_result',{p_id:id,p_claim:c}),
  async markRead(){await sb.from('notifications').update({read:true}).eq('user_id',UID).eq('read',false)},
  async refresh(){const{data:{session}}=await sb.auth.getSession();
   if(!session){const had=!!S.user;S.user=null;return had}
   const uid=UID=session.user.id,q=(t,c)=>sb.from(t).select(c);
   const[p,w,f,l,n,st,mb,tk,wd,an]=await Promise.all([q('profiles','phone,name,ref_code,kyc_status,kyc_note').eq('id',uid).single(),q('wallets','deposit,winning').eq('user_id',uid).single(),
    q('battle_feed','id,stake,prize,status,creator,creator_name,opponent_name').order('created_at',{ascending:false}).limit(30),
    q('wallet_ledger','amount,kind,note,created_at').eq('user_id',uid).order('created_at',{ascending:false}).limit(100),
    q('notifications','message,read,created_at').eq('user_id',uid).order('created_at',{ascending:false}).limit(30),sb.rpc('my_stats'),sb.rpc('my_battles'),q('support_tickets','id,subject,status,reply,created_at').eq('user_id',uid).order('created_at',{ascending:false}).limit(20),q('withdrawals','id,amount,status,payout_method,created_at').eq('user_id',uid).order('created_at',{ascending:false}).limit(10),
    sb.from('announcements').select('message').eq('active',true).or('expires_at.is.null,expires_at.gt.'+new Date().toISOString()).order('created_at',{ascending:false}).limit(1).then(r=>r,()=>({data:null}))]);
   if(p.error||w.error)return false;const old=JSON.stringify(S),s=st.data||{};
   S.user={phone:p.data.phone,name:p.data.name,ref:p.data.ref_code,kyc:p.data.kyc_status==='verified',kycs:p.data.kyc_status,kycNote:p.data.kyc_note,funds:+w.data.deposit,income:+w.data.winning,won:+(s.won||0),games:+(s.games||0),refs:+(s.refs||0),refEarn:+(s.refearn||0)};S.ann=(!an.error&&an.data&&an.data[0]&&String(an.data[0].message||'').trim())||'';S.mine=mb.data||[];S.tickets=tk.data||[];S.wds=(wd.data||[]).map(x=>({id:x.id,amount:+x.amount,status:x.status,method:x.payout_method,at:new Date(x.created_at).getTime()}));
   S.battles=(f.data||[]).map(b=>({id:b.id,st:b.status,by:b.creator_name,opp:b.opponent_name,stake:+b.stake,prize:+b.prize,mine:b.creator===uid}));
   S.ledger=(l.data||[]).map(x=>({t:x.note||x.kind,a:+x.amount,at:new Date(x.created_at).getTime()}));
   S.notes=(n.data||[]).map(x=>({m:x.message,r:x.read,at:new Date(x.created_at).getTime()}));
   return JSON.stringify(S)!==old},
  async boot(){await API.refresh();sb.auth.onAuthStateChange(ev=>{if(ev==='SIGNED_OUT'&&S.user){S.user=null;render()}})}
 })}
