const cl=(r,c,f)=>`<rect x="${c}" y="${r}" width="1" height="1" fill="${f}" stroke="#cfc6ee" stroke-width=".05"/>`;
for(let k=0;k<15;k++){for(const d of[6,7,8]){if(k<6||k>8){o+=cl(d,k,d===7&&k>0&&k<6?'url(#hy0)':d===7&&k>8&&k<14?'url(#hy2)':'#fff');o+=cl(k,d,d===7&&k>0&&k<6?'url(#hy1)':d===7&&k>8&&k<14?'url(#hy3)':'#fff')}}}
