function syncShown(st){const sh=G.shown=G.shown||{};G.seq=G.seq||{};let end=0;const jumps=[];
 st.seats.forEach(q=>{const cur=sh[q]=sh[q]||[...st.tok[q]];st.tok[q].forEach((p,i)=>{const from=cur[i];if(from===p)return;const key=q+':'+i,id=G.seq[key]=(G.seq[key]||0)+1;
  if(from>=0&&p>from){const n=p-from;end=Math.max(end,n*150);for(let k=1;k<=n;k++)setTimeout(()=>{if(G.seq[key]!==id)return;cur[i]=from+k;drawAll()},k*150)}else jumps.push([cur,i,p,key,id])})});
 G.animEnd=Date.now()+end;jumps.forEach(([cur,i,p,key,id])=>setTimeout(()=>{if(G.seq[key]!==id)return;cur[i]=p;drawAll()},end+(end?60:0)));if(end)setTimeout(drawAll,end+80)}
