/* ---- QR payment screen: UI only. Success is shown ONLY after the server (webhook-verified DB status) says so. ---- */
let PY={};
const mmss=s=>String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0');
async function payLoad(){if(!PY.id)return;const id=PY.id,x=await API.apiF('/api/payments/status?order_id='+encodeURIComponent(id));if(PY.id!==id)return;
 if(x.error){PY.err=x.error;paintPay();return}
 const was=PY.data&&PY.data.status;PY.data={...(PY.data||{}),...x};PY.exp=Date.now()+(new Date(x.expires_at)-x.now);if(x.qr)PY.data.qrKeep=x.qr;
 if(x.status!=='pending'){clearInterval(PY.poll);clearInterval(PY.tick);if(x.status==='success'&&was!=='success')API.refresh().then(()=>{const h=$('#app>header');h&&(h.outerHTML=head())})}paintPay()}
function startPay(id){if(PY.id===id&&PY.data){paintPay();return}stopPay();if(!REAL||!/^fb_[a-f0-9]{32}$/.test(id||'')){location.hash='#/wallet';return}PY={id};payLoad();PY.poll=setInterval(payLoad,3000);PY.tick=setInterval(paintPay,1000)}
function stopPay(){clearInterval(PY.poll);clearInterval(PY.tick);PY={}}
function paintPay(){const el=$('#pay');if(!el)return;const d=PY.data;
 const top=`<div class="amh"><button class="gb" data-a="${d&&d.status==='pending'?'amback':'paydone'}" aria-label="Back">${ic('arr')}</button><b>Pay</b><span class="secure">${ic('shield')} Secure</span></div>`;
 if(!d){el.innerHTML=top+(PY.err?`<p class="empty">${esc(PY.err==='NOT_FOUND'?'Payment not found.':'Could not load this payment.')}</p><button class="btn" data-a="payretry">Add Money</button>`:'<p class="empty">Loading payment…</p>');return}
 const amt=fmt(d.amount);let secs=Math.max(0,Math.ceil((PY.exp-Date.now())/1000)),st=d.status;
 if(st==='pending'&&secs<=0){st='expired';d.status='expired';clearInterval(PY.poll);payLoad()}
 if(st==='pending'){const cur=el.querySelector('.qrt');if(cur&&el.dataset.s==='pending'){cur.textContent=mmss(secs);return}
  el.dataset.s='pending';el.innerHTML=top+`<div class="pcard"><div class="brand">${logo}</div><h3>Scan QR to Pay</h3><small>Amount to pay</small><div class="pamt">${amt}</div><div class="qrbox"><img id="qr" src="${d.qr||d.qrKeep||''}" alt="Payment QR for ${esc(amt)}"></div><div class="qrx">QR expires in <b class="qrt ${secs<60?'low':''}">${mmss(secs)}</b></div><div class="pref">Order: ${esc(d.reference||'')}</div><button class="btn" data-a="qrdl">Download QR</button><div class="wait"><i></i><i></i><i></i> Waiting for payment…</div><p class="pnote">Open any UPI app, scan this QR and pay. This page updates automatically.</p></div>`;return}
 el.dataset.s=st;
 const box=st==='success'?`<div class="pst ok"><span>${ic('check')}</span><h3>Payment Successful</h3><p>${amt} payment received</p><button class="btn ok" data-a="paydone">Back to wallet</button></div>`
  :st==='failed'?`<div class="pst bad"><span>${ic('x')}</span><h3>Payment Failed</h3><p>Please try again</p><button class="btn" data-a="payretry">Try again</button></div>`
  :`<div class="pst ex"><span>${ic('clock')}</span><h3>QR Expired</h3><p>This QR is no longer valid.</p><button class="btn" data-a="qrnew">Generate New QR</button></div>`;
 el.innerHTML=top+`<div class="pcard">${box}<div class="pref">Order: ${esc(d.reference||'')}</div></div>`}
async function qrDownload(){const d=PY.data,src=d&&(d.qr||d.qrKeep);if(!d||d.status!=='pending'||!src)return toast('QR not available');
 const save=(blob)=>{const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='NightEliteLudo-PAY-'+String(d.reference||'').replace(/^[A-Za-z]+-/,'')+'.png';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),5000);toast('QR downloaded')};
 try{const img=await new Promise((ok,no)=>{const i=new Image();i.onload=()=>ok(i);i.onerror=no;i.src=src}),c=document.createElement('canvas');c.width=640;c.height=860;const g=c.getContext('2d');
  g.fillStyle='#fff';g.fillRect(0,0,640,860);g.fillStyle='#2b2a33';g.textAlign='center';g.font='700 40px sans-serif';g.fillText('Night Elite Ludo',320,70);g.font='500 26px sans-serif';g.fillStyle='#6f6b78';g.fillText('Amount to pay',320,125);g.font='800 64px sans-serif';g.fillStyle='#2b2a33';g.fillText(fmt(d.amount),320,200);
  g.drawImage(img,70,230,500,500);g.font='500 24px sans-serif';g.fillStyle='#6f6b78';g.fillText('Order: '+d.reference,320,785);g.font='500 20px sans-serif';g.fillText('Scan with any UPI app',320,825);
  const b=await new Promise(r=>c.toBlob(r,'image/png'));if(!b)throw 0;save(b)}
 catch{try{const b=await fetch(src).then(r=>r.blob());save(b)}catch{window.open(src,'_blank');toast('Long-press the QR to save it')}}}
let KB={};
const shrink=(f,max=1280)=>new Promise((ok,no)=>{if(!/^image\//.test(f.type))return no(Error('Choose an image file.'));const u=URL.createObjectURL(f),i=new Image();i.onload=()=>{URL.revokeObjectURL(u);const k=Math.min(1,max/Math.max(i.width,i.height)),c=document.createElement('canvas');c.width=Math.round(i.width*k);c.height=Math.round(i.height*k);c.getContext('2d').drawImage(i,0,0,c.width,c.height);const go=q=>c.toBlob(b=>!b?no(Error('Could not process the image.')):b.size>450e3&&q>.4?go(q-.12):ok(b),'image/jpeg',q);go(.72)};i.onerror=()=>{URL.revokeObjectURL(u);no(Error('Could not read this image. Use a JPG or PNG photo.'))};i.src=u});
